CREATE TABLE exam_matrices(id UUID PRIMARY KEY,name VARCHAR(255) NOT NULL,faculty_id VARCHAR(50) NOT NULL,subject_id UUID NOT NULL,total_questions INTEGER NOT NULL,created_by UUID NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT ck_matrix_total CHECK(total_questions>0));
CREATE TABLE exam_matrix_rules(id UUID PRIMARY KEY,matrix_id UUID NOT NULL REFERENCES exam_matrices(id) ON DELETE CASCADE,chapter_id UUID NOT NULL,topic_id UUID,difficulty VARCHAR(20) NOT NULL,question_count INTEGER NOT NULL,CONSTRAINT ck_rule_count CHECK(question_count>=0),CONSTRAINT ck_rule_difficulty CHECK(difficulty IN('EASY','MEDIUM','HARD')));
CREATE INDEX idx_matrix_rule ON exam_matrix_rules(matrix_id,chapter_id,topic_id,difficulty);
CREATE TABLE exam_templates(id UUID PRIMARY KEY,name VARCHAR(255) NOT NULL,faculty_id VARCHAR(50) NOT NULL,matrix_id UUID NOT NULL REFERENCES exam_matrices(id),header TEXT,instructions TEXT,created_by UUID NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE exams(id UUID PRIMARY KEY,name VARCHAR(255) NOT NULL,faculty_id VARCHAR(50) NOT NULL,subject_id UUID NOT NULL,matrix_id UUID NOT NULL REFERENCES exam_matrices(id),template_id UUID REFERENCES exam_templates(id),created_by UUID NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE exam_versions(id UUID PRIMARY KEY,exam_id UUID NOT NULL REFERENCES exams(id) ON DELETE CASCADE,version_number INTEGER NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_exam_version UNIQUE(exam_id,version_number));
CREATE TABLE exam_question_references(id UUID PRIMARY KEY,exam_version_id UUID NOT NULL REFERENCES exam_versions(id) ON DELETE CASCADE,question_id UUID NOT NULL,position INTEGER NOT NULL,matrix_rule_id UUID NOT NULL,CONSTRAINT uk_version_question UNIQUE(exam_version_id,question_id),CONSTRAINT uk_version_position UNIQUE(exam_version_id,position));
CREATE INDEX idx_matrix_faculty ON exam_matrices(faculty_id,updated_at);CREATE INDEX idx_exam_faculty ON exams(faculty_id,created_at);CREATE INDEX idx_question_reference ON exam_question_references(question_id);
